export function facilityText(english, values = {}, language = menuLanguage()) {
  if (!english) return '';
  const index = languages.indexOf(language.startsWith('es') ? 'es' : language);
  let result = english;
  if (index !== -1) {
    const requirement = /^Requires (.+)\.$/.exec(english);
    if (requirement) return dossierLabel('Requires', language) + ' ' + dossierLabel(requirement[1], language) + '.';
    const mark = /^(Costs|Risk)([¹²])$|^(◆|◇) (Latest discovery|Previous discovery)$/.exec(english);
    if (mark) return mark[1] ? facilityText(mark[1], {}, language) + mark[2] : mark[3] + ' ' + facilityText(mark[4], {}, language);
    const key = terms.has(english) ? english : aliases[english] || english;
    result = terms.get(key)?.[index] ?? dossierLabel(key, language);
  }
  if (!result.includes('{')) return result;
  return result.replace(/\{(\w+)\}/g, (match, key) => Object.hasOwn(values, key) ? String(values[key]) : match);
}

// Run only on the initial static controls, before any player-supplied name is inserted.
export function localizeFacilityMarkup(root) {
  if (menuLanguage() === 'en') return;
  const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) {
    const text = walker.currentNode;
    const label = text.nodeValue.trim();
    if (label) text.nodeValue = text.nodeValue.replace(label, () => facilityText(label));
  }
  for (const node of root.querySelectorAll('[aria-label]')) node.setAttribute('aria-label', facilityText(node.getAttribute('aria-label')));
}
